    const brands=[...new Set(all.map(r=>r.brand))];
    const timelineOptions=[['before','17:30 前 · 用户可调整'],['frozen','17:30 已冻结 · 待确认表'],['locked','20:00 已锁定 · 最终任务']].map(([v,label])=>`<option value="${v}" ${state.timeline===v?'selected':''}>${label}</option>`).join('');
